program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [value for value in counts if value != background]
    foreground = max(colors, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == foreground]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the outline of the foreground's bounding rectangle.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if grid[r][c] == background:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Restore gaps in any strongly established interior straight line.
    for r in range(r0 + 1, r1):
        positions = [c for c in range(w) if grid[r][c] == foreground]
        if len(positions) >= 4:
            for c in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(c0 + 1, c1):
        positions = [r for r in range(h) if grid[r][c] == foreground]
        if len(positions) >= 4:
            for r in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
'''
